const { rng, fbm, noise, clamp, smooth, lerp, canvas } = window.GZ;
const rgb = (c, a = 1) => `rgba(${c[0] | 0},${c[1] | 0},${c[2] | 0},${a})`;

function polyPath(c, pts, W, H, dx = 0, dy = 0) {
  c.beginPath();
  for (let i = 0; i < pts.length; i++) { const x = pts[i][0] * W + dx, y = pts[i][1] * H + dy; i ? c.lineTo(x, y) : c.moveTo(x, y); }
  c.closePath();
}
// stepped skyline path from [x0,y] runs
function stepPath(c, steps, W, H, bottom) {
  c.beginPath(); c.moveTo(-2, bottom);
  for (let i = 0; i < steps.length; i++) {
    const x0 = i === 0 ? -2 : steps[i][0] * W, x1 = i + 1 < steps.length ? steps[i + 1][0] * W : W + 2, y = Math.min(steps[i][1] * H, bottom);
    c.lineTo(x0, y); c.lineTo(x1, y);
  }
  c.lineTo(W + 2, bottom); c.closePath();
}
function segments(steps, W, H) {
  const s = [];
  for (let i = 0; i < steps.length; i++) {
    const x0 = i === 0 ? 0 : steps[i][0] * W, x1 = i + 1 < steps.length ? steps[i + 1][0] * W : W, y = steps[i][1] * H;
    s.push({ x0, x1, y });
  }
  return s;
}

// ---------- sky ----------
function bakeSky(W, H) {
  const c = canvas(W, H), x = c.getContext('2d');
  const g = x.createLinearGradient(0, 0, 0, H);
  for (const s of D.sky) g.addColorStop(s[0], rgb([s[1], s[2], s[3]]));
  g.addColorStop(0.64, 'rgb(205,48,15)'); g.addColorStop(0.68, 'rgb(212,52,13)');
  g.addColorStop(0.72, 'rgb(222,58,11)'); g.addColorStop(0.77, 'rgb(236,68,12)');
  g.addColorStop(0.82, 'rgb(215,40,8)'); g.addColorStop(0.88, 'rgb(90,4,4)'); g.addColorStop(1, 'rgb(20,0,2)');
  x.fillStyle = g; x.fillRect(0, 0, W, H);
  // a whisper of cloud texture in the upper sky (the reference is flat here; this keeps it from feeling dead)
  const s = 8, cw = Math.ceil(W / s), ch = Math.ceil(H * 0.6 / s), cc = canvas(cw, ch), cx = cc.getContext('2d'), d = cx.createImageData(cw, ch);
  for (let j = 0; j < ch; j++) for (let i = 0; i < cw; i++) {
    const n = fbm(i / cw * 3.2, j / ch * 9 + 2, 4), k = (j * cw + i) * 4;
    const v = n * 0.5 + 0.5;
    d.data[k] = v > 0.5 ? 255 : 60; d.data[k + 1] = v > 0.5 ? 60 : 0; d.data[k + 2] = v > 0.5 ? 30 : 0; d.data[k + 3] = Math.abs(v - 0.5) * 30;
  }
  cx.putImageData(d, 0, 0);
  x.save(); x.imageSmoothingQuality = 'high'; x.drawImage(cc, 0, 0, W, H * 0.6); x.restore();
  // warm horizon haze, brighter behind the burning right side
  const hz = (cx0, cy, rx, ry, col, a) => { x.save(); x.translate(cx0 * W, cy * H); x.scale(1, ry / rx); const r = x.createRadialGradient(0, 0, 0, 0, 0, rx * W); r.addColorStop(0, rgb(col, a)); r.addColorStop(1, rgb(col, 0)); x.fillStyle = r; x.fillRect(-rx * W, -rx * W, rx * W * 2, rx * W * 2); x.restore(); };
  x.globalCompositeOperation = 'screen';
  hz(0.80, 0.665, 0.42, 0.11 * 2, [120, 40, 0], 0.55);
  hz(1.00, 0.655, 0.22, 0.05 * 2, [140, 60, 10], 0.6);
  hz(0.55, 0.74, 0.5, 0.06 * 2, [110, 35, 0], 0.5);
  x.globalCompositeOperation = 'source-over';
  // mouth halo spilling onto the sky in front of the jaws (sits behind the head)
  x.save(); x.translate(0.331 * W, 0.4878 * H); x.scale(1, 0.84);
  let r = x.createRadialGradient(0, 0, 0, 0, 0, 0.06 * W);
  r.addColorStop(0, 'rgba(252,110,38,0.7)'); r.addColorStop(0.4, 'rgba(242,72,24,0.3)'); r.addColorStop(1, 'rgba(225,40,15,0)');
  x.fillStyle = r; x.fillRect(-0.07 * W, -0.07 * W, 0.14 * W, 0.14 * W); x.restore();
  // very fine atmospheric dither so the long gradient never bands
  const rr = rng(11); x.globalAlpha = 0.035;
  for (let i = 0; i < W * H / 260; i++) { x.fillStyle = rr() < 0.5 ? '#000' : '#fff'; x.fillRect(rr() * W, rr() * H * 0.8, 1, 1); }
  x.globalAlpha = 1;
  return c;
}

