  const dk = 1 - 0.0 * smooth(0.64, 0.75, yn) * (1 - smooth(0.76, 0.80, yn));
  out[0] *= dk; out[1] *= dk; out[2] *= dk;
  // forearm + claw: deep maroon, crisp against the haze
  const arm = smooth(0.392, 0.372, xn) * smooth(0.685, 0.7, yn);
