      const N = (n - 1) * 9, L = [], R = [];
      let lx = 0, ly = 0;
      for (let k = 0; k <= N; k++) {
        const f = k / N * (n - 1), i = Math.min(n - 2, f | 0), u = f - i, p0 = P(i - 1), p1 = P(i), p2 = P(i + 1), p3 = P(i + 2);
        const u2 = u * u, u3 = u2 * u;
        const cx = 0.5 * (2 * p1[0] + (p2[0] - p0[0]) * u + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * u2 + (3 * p1[0] - p0[0] - 3 * p2[0] + p3[0]) * u3);
        const cy = 0.5 * (2 * p1[1] + (p2[1] - p0[1]) * u + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u2 + (3 * p1[1] - p0[1] - 3 * p2[1] + p3[1]) * u3);
        if (k === 0) { lx = cx; ly = cy; L.push(cx, cy); R.push(cx, cy); continue; }
        const dx = cx - lx, dy = cy - ly, d = Math.hypot(dx, dy) || 1, s = k / N;
        // brush profile: quick swell, long taper to a hair
        const hw = wpx * 0.5 * Math.pow(Math.sin(Math.PI * Math.pow(s, 0.8)), 0.55);
        L.push(cx - dy / d * hw, cy + dx / d * hw); R.push(cx + dy / d * hw, cy - dx / d * hw);
        lx = cx; ly = cy;
      }
