  // fill the old (unmeasured) mouth opening with head first, so only the traced interior glows
  b.save(); b.globalCompositeOperation = 'source-over';
  b.beginPath(); b.moveTo(0.3345 * W, 0.4795 * H); b.lineTo(0.3975 * W, 0.4840 * H); b.lineTo(0.3975 * W, 0.5005 * H); b.lineTo(0.3310 * W, 0.4988 * H); b.closePath();
